'use strict';

var uniform = require( '@stdlib/random/array/uniform' );
var logEachMap = require( '@stdlib/console/log-each-map' );
var polevl = require( './../lib' );

// Polynomial coefficients (constant-first order):

// p(x) = 1 + 2x + 3x^2

var coef = [ 1.0, 2.0, 3.0 ];
var N = 2;

var x = uniform( 100, -2.0, 2.0, {
	'dtype': 'float64'
});

function map( v ) {
	return polevl( v, coef, N );
}

logEachMap( 'polevl(%lf) = %lf', x, map );
